import app from 'flarum/admin/app';
import FormModal from 'flarum/common/components/FormModal';
import Button from 'flarum/common/components/Button';
import Stream from 'flarum/common/utils/Stream';
const t = (key, params) => app.translator.trans(`ernestdefoe-salvage.admin.replace_modal.${key}`, params);

/** Asks for the address a broken link should point to instead. */
export default class ReplaceModal extends FormModal {
  oninit(vnode) {
    super.oninit(vnode);
    this.url = Stream(this.attrs.link.replacement || '');
  }
  className() {
    return 'SalvageReplaceModal Modal--small';
  }
  title() {
    return t('title');
  }
  content() {
    return m("div", {
      className: "Modal-body"
    }, m("p", {
      className: "helpText"
    }, t('help')), m("p", {
      className: "SalvageReplaceModal-old"
    }, this.attrs.link.url), m("div", {
      className: "Form-group"
    }, m("label", {
      for: "salvage-replacement"
    }, t('label')), m("input", {
      id: "salvage-replacement",
      name: "action",
      className: "FormControl",
      type: "url",
      required: true,
      bidi: this.url,
      placeholder: "https://"
    })), m(Button, {
      type: "submit",
      className: "Button Button--primary",
      loading: this.loading
    }, t('submit')));
  }
  onsubmit(e) {
    e.preventDefault();
    this.loading = true;
    this.attrs.onsubmit(this.url().trim()).then(() => this.hide()).catch(error => {
      this.loading = false;
      this.onerror(error);
    });
  }
}